"""Read-only person-cap proof and lossless offline encoding experiment."""
from test_mobile_rendering import ROOT,html
from playwright.sync_api import sync_playwright
import json,hashlib
source=(ROOT/'assets/game.js').read_text();probe=r'''
window.__personAudit={boundary:()=>{__townTest.reset('settlement',42);__townTest.step(30);G.day=90;while(G.people.length<8000)G.people.push({id:G.people.length,name:'Synthetic retired identity',age:96,hh:0,job:-1,health:0,skill:.5,life:80,last:[],deceased:true});const baseline=archivePayload();if(!hydrateSave(baseline))throw Error('8000 boundary rejected');for(let n=1;n<=100;n++){hydrateSave(baseline);rngState=n;G.rngState=n;const before=G.people.length,cash=totalMoney(),priorHomes=JSON.stringify(G.households.map(h=>[h.id,h.home,h.cash,h.deposits])),titles=JSON.stringify(G.buildings.map(b=>[b.id,b.owner,b.title]));birthsAndGenerations();if(G.people.length===before)continue;recompute();G.rngState=rngState;const homesPreserved=JSON.stringify(G.households.map(h=>[h.id,h.home,h.cash,h.deposits]))===priorHomes;const raw=archivePayload(),size=G.people.length,live=G.stats.population,valid=validateTown();const accepted=hydrateSave(raw);if(accepted)throw Error('Expected current cap rejection');if(!hydrateSave(baseline))throw Error('Previous town lost');return {rngSeed:n,syntheticInactiveHistory:8000-before+8000,recordsBefore:before,recordsAfter:size,newBirths:size-before,livingAfter:live,priorWalletsAndAddressesPreserved:homesPreserved,creator:'birthsAndGenerations',importAccepted:accepted,structureValidBeforeImport:valid.ok,cashPreserved:totalMoney()===cash,priorTitlesPreserved:JSON.stringify(G.buildings.map(b=>[b.id,b.owner,b.title]))===titles,archiveHash:checksum(raw)};}throw Error('No seeded birth');},natural:()=>{__townTest.reset('settlement',42);const samples=[];let minimum=G.people.length;for(let block=1;block<=10;block++){__townTest.step(720);if(G.people.length<minimum)throw Error('Identity array shortened');minimum=G.people.length;samples.push({year:block*2,records:G.people.length,living:G.people.filter(p=>!p.deceased&&!p.movedAway).length,deceased:G.people.filter(p=>p.deceased).length,departed:G.people.filter(p=>p.movedAway).length,retired:G.people.filter(p=>p.retired).length,personBytes:new Blob([JSON.stringify(G.people)]).size,households:G.households.length});}return {samples,people:JSON.parse(JSON.stringify(G.people))};}};
'''
with sync_playwright() as pw:
 b=pw.chromium.launch(executable_path='/usr/bin/chromium',args=['--no-sandbox']);p=b.new_page();p.set_default_timeout(240000);p.set_content(html);p.add_script_tag(content=source.replace('// SOURCE: 99-instrumentation.js',probe+'\n// SOURCE: 99-instrumentation.js'));p.locator('#newTown').click();p.locator('#pause').click();r={'source_sha256':hashlib.sha256(source.encode()).hexdigest(),'boundary':p.evaluate('__personAudit.boundary()')};print('Boundary',r['boundary'],flush=True);natural=p.evaluate('__personAudit.natural()');b.close()
people=natural.pop('people');canonical=lambda v:json.dumps(v,sort_keys=True,separators=(',',':'),ensure_ascii=False)
# Offline, complete-record dictionary encoding. No model or validator consumes it.
fields=sorted({k for p in people for k in p if k!='id'});packed={'version':1,'fields':fields,'rows':[[p['id'],[i for i,k in enumerate(fields) if k in p],[p[k] for k in fields if k in p]] for p in people]};decoded=[dict([('id',row[0])]+[(fields[i],value) for i,value in zip(row[1],row[2])]) for row in packed['rows']];assert canonical(decoded)==canonical(people)
r['natural']=natural;r['offlineEncoding']={'allFieldsAndIdsEqual':True,'records':len(people),'originalBytes':len(canonical(people).encode()),'packedBytes':len(canonical(packed).encode()),'decodedSha256':hashlib.sha256(canonical(decoded).encode()).hexdigest(),'productionFormat':False};out=ROOT/'reports/person-history';out.mkdir(exist_ok=True);(out/'result.json').write_text(json.dumps(r,indent=2)+'\n');print('PASS read-only proof',json.dumps(r))
